@startuml
class Aircraft {
  +name : string
  +type : string
  +yearOfManufacture : int
  +dateOfNextInspection : date
}

class Flight {
  +flightNumber : string
  +date : date
}

class Passenger {
  +name : string
  +passportNumber : string
}

class Ticket {
  +ticketNumber : string
  +price : double
  +upgradeDesired : boolean
}

class PassengerAircraft extends Aircraft {
  +numberOfSeats : int
}

class SeatCategory {
  +designation : string
  +offersEntertainmentProgram : boolean
  +numberOfSeats : int
}

class Airline {
  +name : string
}

class FlightAttendant {
  +name : string
  +dateOfEmployment : date
  +isChiefStewardess : boolean
}

class Pilot {
  +name : string
  +dateOfEmployment : date
  +license : string
}

class Airport {
  +name : string
  +address : string
  +runwayNumbers : string[]
}

Aircraft "0..*" -- "1" Airline : belongs to
Aircraft "1" -- "0..*" Flight : performs
Passenger "1..*" -- "*" Flight : takes part in
Flight "1" -- "*" Ticket : has
Passenger "1" -- "*" Ticket : holds
Ticket "*" -- "1" SeatCategory : for

PassengerAircraft "1" *-- "1..*" SeatCategory : has

Airline "1" -- "*" FlightAttendant : employs
Airline "1" -- "*" Pilot : employs

Flight "1" -- "1..*" FlightAttendant : employs
Flight "1" -- "1" Pilot : captain
Flight "1" -- "0..2" Pilot : co-pilots

Aircraft "0..*" -- "0..1" Airport : home airport
Flight "1" -- "1" Airport : departure airport
Flight "1" -- "1" Airport : destination airport
@enduml

